parameters.jsCode:
// ---------------------------------------------------------------------------
// Guardrail + Policy Gate
// Mirrors packages/core/src/judge.ts (weighted rubric -> verdict) and
// packages/core/src/guardrail.ts:checkDecisionPolicy (post-assessment gate).
// Self-contained: no external requires, pure JS over $json.
// ---------------------------------------------------------------------------

/** Pulls the first balanced {...} JSON object out of a free-text LLM reply. */
function extractFirstJsonObject(text) {
  const s = String(text ?? '');
  const start = s.indexOf('{');
  if (start === -1) throw new Error('Guardrail: no JSON object found in judge output');
  let depth = 0;
  for (let i = start; i < s.length; i++) {
    if (s[i] === '{') depth++;
    if (s[i] === '}') depth--;
    if (depth === 0) return JSON.parse(s.slice(start, i + 1));
  }
  throw new Error('Guardrail: unterminated JSON object in judge output');
}

function clamp(n, lo, hi) {
  const num = Number(n);
  return Math.min(hi, Math.max(lo, Number.isFinite(num) ? num : lo));
}

// Rubric mirrors the default judge rubric shape used by packages/core/src/judge.ts.
const RUBRIC = {
  criteria: [
    { id: 'accuracy', weight: 0.4 },
    { id: 'evidence_use', weight: 0.3 },
    { id: 'calibration', weight: 0.2 },
    { id: 'clarity', weight: 0.1 },
  ],
  passThreshold: 0.7,
  reviseThreshold: 0.5,
};

// Policy defaults mirror .env.example (POLICY_MIN_CONFIDENCE / bannedMarkets).
const POLICY = {
  minConfidence: 0.55,
  bannedMarkets: [],
};

const judgeText = $json.output ?? $json.text ?? '{}';
const judgeRaw = extractFirstJsonObject(judgeText);

const criteria = {};
let overall = 0;
for (const c of RUBRIC.criteria) {
  const v = clamp(judgeRaw[c.id], 0, 1);
  criteria[c.id] = v;
  overall += v * c.weight;
}

const verdict =
  overall >= RUBRIC.passThreshold ? 'pass' : overall >= RUBRIC.reviseThreshold ? 'revise' : 'reject';

// The analyst's own assessed probability doubles as "confidence" for the
// policy gate (mirrors AgentAssessment.probability in checkDecisionPolicy).
let assessmentProbability = 0;
try {
  const analystJson = extractFirstJsonObject($('AI Agent: Analyst').first().json.output ?? '{}');
  assessmentProbability = clamp(analystJson.probability, 0, 1);
} catch (err) {
  assessmentProbability = 0;
}

const subject = $json.subject ?? 'unknown-subject';

const violations = [];
if (assessmentProbability < POLICY.minConfidence) {
  violations.push(
    `assessment confidence ${assessmentProbability} is below minConfidence ${POLICY.minConfidence}`,
  );
}
if (POLICY.bannedMarkets.includes(subject)) {
  violations.push(`subject "${subject}" is on the banned markets list`);
}
if (verdict === 'reject') {
  violations.push(`judge verdict is "reject" (overall ${overall.toFixed(3)})`);
}

const approved = violations.length === 0;

return [
  {
    json: {
      subject,
      assessment_probability: assessmentProbability,
      judge_overall: overall,
      judge_criteria: criteria,
      judge_verdict: verdict,
      judge_critique: judgeRaw.critique ?? '',
      policy_approved: approved,
      policy_violations: violations,
    },
  },
];
